#import <Cocoa/Cocoa.h>
#import <WebKit/WebKit.h>
@interface WaveApp : NSObject <NSApplicationDelegate,WKScriptMessageHandler,WKNavigationDelegate>
@property NSWindow *window;@property WKWebView *web;@property NSTask *engine;@property NSPipe *input;@property NSMutableData *buffer;@property NSURL *project;@property BOOL busy;@property BOOL qemu;@property NSTask *hardwareTask;
@end
@implementation WaveApp
-(NSURL*)res{return NSBundle.mainBundle.resourceURL;}
-(void)applicationDidFinishLaunching:(NSNotification*)n{
 [NSApp setActivationPolicy:NSApplicationActivationPolicyRegular];NSMenu *menu=[NSMenu new];NSMenuItem *item=[NSMenuItem new];[menu addItem:item];NSMenu *sub=[NSMenu new];[sub addItemWithTitle:@"Quit WaveSim" action:@selector(terminate:) keyEquivalent:@"q"];item.submenu=sub;NSApp.mainMenu=menu;
 WKWebViewConfiguration *config=[WKWebViewConfiguration new];[config.userContentController addScriptMessageHandler:self name:@"wave"];self.web=[[WKWebView alloc]initWithFrame:NSZeroRect configuration:config];self.web.navigationDelegate=self;
 self.window=[[NSWindow alloc]initWithContentRect:NSMakeRect(0,0,1240,940) styleMask:NSWindowStyleMaskTitled|NSWindowStyleMaskClosable|NSWindowStyleMaskMiniaturizable|NSWindowStyleMaskResizable backing:NSBackingStoreBuffered defer:NO];self.window.title=@"WaveSim • ESP32-S3-ePaper-1.54 V2";self.window.minSize=NSMakeSize(960,740);self.window.contentView=self.web;self.window.appearance=[NSAppearance appearanceNamed:NSAppearanceNameDarkAqua];[self.window center];[self.window makeKeyAndOrderFront:nil];[self.web loadFileURL:[[self res]URLByAppendingPathComponent:@"index.html"] allowingReadAccessToURL:[self res]];[NSApp activateIgnoringOtherApps:YES];
}
-(void)notice:(NSString*)s{NSData *d=[NSJSONSerialization dataWithJSONObject:@[s?:@"Error"] options:0 error:nil];NSString *json=[[NSString alloc]initWithData:d encoding:NSUTF8StringEncoding];[self.web evaluateJavaScript:[NSString stringWithFormat:@"notice(%@[0])",json] completionHandler:nil];}
-(void)send:(NSDictionary*)j{NSData *d=[NSJSONSerialization dataWithJSONObject:j options:0 error:nil];NSMutableData *line=[d mutableCopy];[line appendBytes:"\n" length:1];@try{[self.input.fileHandleForWriting writeData:line];}@catch(NSException *e){[self notice:e.reason];}}
-(void)webView:(WKWebView*)w didFinishNavigation:(WKNavigation*)n{
 self.engine=[NSTask new];self.input=[NSPipe pipe];NSPipe *out=[NSPipe pipe];self.buffer=[NSMutableData new];if(self.qemu){self.engine.executableURL=[NSURL fileURLWithPath:[[self sourceRoot]stringByAppendingPathComponent:@"third_party/idf-tools/python_env/idf5.5_py3.12_env/bin/python"]];self.engine.arguments=@[[[self sourceRoot]stringByAppendingPathComponent:@"tools/qemu_bridge.py"]];}else self.engine.executableURL=[[self res]URLByAppendingPathComponent:@"wavesim-engine"];self.engine.standardInput=self.input;self.engine.standardOutput=out;
 __weak WaveApp *weak=self;out.fileHandleForReading.readabilityHandler=^(NSFileHandle *h){NSData *d=h.availableData;if(!d.length)return;dispatch_async(dispatch_get_main_queue(),^{WaveApp *s=weak;if(!s)return;[s.buffer appendData:d];while(YES){NSRange r=[s.buffer rangeOfData:[NSData dataWithBytes:"\n" length:1] options:0 range:NSMakeRange(0,s.buffer.length)];if(r.location==NSNotFound)break;NSData *line=[s.buffer subdataWithRange:NSMakeRange(0,r.location)];[s.buffer replaceBytesInRange:NSMakeRange(0,r.location+1) withBytes:NULL length:0];NSString *v=[[NSString alloc]initWithData:line encoding:NSUTF8StringEncoding];if(v)[s.web evaluateJavaScript:[NSString stringWithFormat:@"receive(%@)",v] completionHandler:nil];}});};NSError *error=nil;if(![self.engine launchAndReturnError:&error]){[self notice:error.localizedDescription];return;}[self send:@{@"op":@"load",@"path":[[self.res URLByAppendingPathComponent:@"environment.dylib"]path]}];[self send:@{@"op":@"set",@"epoch":@([NSDate date].timeIntervalSince1970)}];[self send:@{@"op":@"run"}];
}
-(void)build{if(self.qemu){[self notice:@"Rebuild QEMU firmware with tools/idf.sh -C examples/qemu-environment build, then reselect QEMU."];return;}if(self.busy)return;if(!self.project){[self notice:@"Bundled examples are precompiled. Open a project to build edited source."];return;}NSString *output=[NSTemporaryDirectory() stringByAppendingPathComponent:[NSString stringWithFormat:@"wavesim-%@.dylib",NSUUID.UUID.UUIDString]];NSTask *p=[NSTask new];p.executableURL=[NSURL fileURLWithPath:@"/usr/bin/python3"];p.arguments=@[[[self.res URLByAppendingPathComponent:@"Source/tools/build_project.py"]path],self.project.path,output];NSPipe *pipe=[NSPipe pipe];p.standardOutput=pipe;p.standardError=pipe;self.busy=YES;[self notice:[@"Compiling " stringByAppendingString:self.project.path]];dispatch_async(dispatch_get_global_queue(0,0),^{NSError *e=nil;BOOL ok=[p launchAndReturnError:&e];NSData *data=ok?[pipe.fileHandleForReading readDataToEndOfFile]:nil;if(ok)[p waitUntilExit];dispatch_async(dispatch_get_main_queue(),^{self.busy=NO;if(ok&&p.terminationStatus==0){[self notice:[[NSString alloc]initWithData:data encoding:NSUTF8StringEncoding]];NSData *selection=[NSJSONSerialization dataWithJSONObject:@[self.project.path] options:0 error:nil];[self.web evaluateJavaScript:[NSString stringWithFormat:@"projectOpened(%@[0])",[[NSString alloc]initWithData:selection encoding:NSUTF8StringEncoding]] completionHandler:nil];[self send:@{@"op":@"load",@"path":output}];[self send:@{@"op":@"run"}];}else [self notice:ok?[[NSString alloc]initWithData:data encoding:NSUTF8StringEncoding]:e.localizedDescription];});});}
-(NSString*)sourceRoot{NSDictionary *d=[NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfURL:[self.res URLByAppendingPathComponent:@"development.json"]] options:0 error:nil];return d[@"sourceRoot"];}
-(void)hardware:(NSDictionary*)j{
 NSString *action=j[@"action"],*root=[self sourceRoot];
 if([action isEqual:@"stop"]){if(self.hardwareTask.running)[self.hardwareTask terminate];return;}
 if([action isEqual:@"list"]){NSArray *files=[[NSFileManager defaultManager]contentsOfDirectoryAtPath:@"/dev" error:nil];NSMutableArray *ports=[NSMutableArray new];for(NSString *f in files)if([f hasPrefix:@"cu.usb"])[ports addObject:[@"/dev/" stringByAppendingString:f]];NSData *d=[NSJSONSerialization dataWithJSONObject:ports options:0 error:nil];[self.web evaluateJavaScript:[NSString stringWithFormat:@"ports(%@)",[[NSString alloc]initWithData:d encoding:NSUTF8StringEncoding]] completionHandler:nil];return;}
 if(self.hardwareTask.running){[self notice:@"A hardware command is running; stop it first."];return;}
 if(self.project&&([action isEqual:@"build"]||[action isEqual:@"flash"])){BOOL dir=NO;[[NSFileManager defaultManager]fileExistsAtPath:self.project.path isDirectory:&dir];NSString *cmake=[self.project.path stringByAppendingPathComponent:@"CMakeLists.txt"];if(!dir||![[NSFileManager defaultManager]fileExistsAtPath:cmake]){[self notice:@"Physical build/flash currently requires an ESP-IDF project. Use Arduino IDE/CLI for these .ino projects."];return;}}
 NSString *port=j[@"port"]?:@"";if(![action isEqual:@"build"]&&![port hasPrefix:@"/dev/cu.usb"]){[self notice:@"Choose a detected USB serial port first."];return;}
 NSTask *p=[NSTask new];NSMutableArray *args=[NSMutableArray new];
 if([action isEqual:@"build"]||[action isEqual:@"flash"]){p.executableURL=[NSURL fileURLWithPath:[root stringByAppendingPathComponent:@"tools/idf.sh"]];NSString *project=self.project.path?:[root stringByAppendingPathComponent:@"examples/environment"];[args addObjectsFromArray:@[@"-C",project]];if([action isEqual:@"flash"])[args addObjectsFromArray:@[@"-p",port]];[args addObject:action];}
 else if([action isEqual:@"monitor"]){p.executableURL=[NSURL fileURLWithPath:[root stringByAppendingPathComponent:@"third_party/idf-tools/python_env/idf5.5_py3.12_env/bin/python"]];[args addObjectsFromArray:@[[root stringByAppendingPathComponent:@"tools/monitor.py"],port]];}
 else { [self notice:@"Unsupported hardware action"];return; }
 p.arguments=args;NSPipe *pipe=[NSPipe pipe];p.standardOutput=pipe;p.standardError=pipe;self.hardwareTask=p;
 pipe.fileHandleForReading.readabilityHandler=^(NSFileHandle *h){NSData *data=h.availableData;if(!data.length)return;NSString *str=[[NSString alloc]initWithData:data encoding:NSUTF8StringEncoding];dispatch_async(dispatch_get_main_queue(),^{NSData *d=[NSJSONSerialization dataWithJSONObject:@[str?:@""] options:0 error:nil];[self.web evaluateJavaScript:[NSString stringWithFormat:@"hardwareLog(%@[0])",[[NSString alloc]initWithData:d encoding:NSUTF8StringEncoding]] completionHandler:nil];});};
 p.terminationHandler=^(NSTask *t){dispatch_async(dispatch_get_main_queue(),^{[self notice:[NSString stringWithFormat:@"Hardware %@ exited %d",action,t.terminationStatus]];});};NSError *e=nil;if(![p launchAndReturnError:&e])[self notice:e.localizedDescription];else [self notice:[@"Hardware command started: " stringByAppendingString:action]];
}
-(void)userContentController:(WKUserContentController*)c didReceiveScriptMessage:(WKScriptMessage*)m{
 if(![m.body isKindOfClass:NSDictionary.class])return;NSDictionary *j=m.body;NSString *op=j[@"op"];
 if([op isEqual:@"backend"]){self.qemu=[j[@"qemu"]boolValue];if(self.engine.running){[self.input.fileHandleForWriting closeFile];[self.engine waitUntilExit];}[self webView:self.web didFinishNavigation:nil];[self notice:self.qemu?@"QEMU booting: compiled Xtensa dashboard, UART peripheral bridge":@"Native C backend ready"];}
 else if([op isEqual:@"hardware"]){[self hardware:j];}
 else if([op isEqual:@"example"]){NSString *name=j[@"name"];if(self.qemu&&![name isEqual:@"environment"]){[self notice:@"QEMU bridge currently runs Environment only. Select Native C for other examples."];return;}if(![@[@"environment",@"hello",@"network"]containsObject:name])return;self.project=nil;[self send:@{@"op":@"load",@"path":[[self.res URLByAppendingPathComponent:[name stringByAppendingString:@".dylib"]]path]}];[self send:@{@"op":@"run"}];}
 else if([op isEqual:@"open"]){NSOpenPanel *p=[NSOpenPanel openPanel];p.canChooseDirectories=YES;p.message=@"Choose an Arduino .ino/sketch folder or a WaveSim project containing main/app.c";if(p.runModal==NSModalResponseOK){self.project=p.URL;[self build];}}
 else if([op isEqual:@"build"])[self build];
 else if([op isEqual:@"save"]){NSSavePanel *p=[NSSavePanel savePanel];p.nameFieldStringValue=j[@"name"]?:@"wavesim.txt";if(p.runModal==NSModalResponseOK){NSData *d=[j[@"base64"]boolValue]?[[NSData alloc]initWithBase64EncodedString:j[@"data"] options:0]:[j[@"data"]dataUsingEncoding:NSUTF8StringEncoding];NSError *e=nil;if(![d writeToURL:p.URL options:NSDataWritingAtomic error:&e])[self notice:e.localizedDescription];}}
 else if([op isEqual:@"sd_choose"]){NSOpenPanel *p=[NSOpenPanel openPanel];p.canChooseDirectories=YES;p.canChooseFiles=NO;if(p.runModal==NSModalResponseOK){[self send:@{@"op":@"set",@"sd":p.URL.path}];[self notice:[@"SD mounted: " stringByAppendingString:p.URL.path]];}}
 else if([op isEqual:@"replay_file"]){NSOpenPanel *p=[NSOpenPanel openPanel];if(p.runModal==NSModalResponseOK){NSError *e=nil;id steps=[NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfURL:p.URL] options:0 error:&e];if([steps isKindOfClass:NSArray.class])[self send:@{@"op":@"replay",@"steps":steps}];else [self notice:@"Scenario must contain a JSON array of commands."];}}
 else if([op isEqual:@"reveal"])[NSWorkspace.sharedWorkspace openURL:[self.res URLByAppendingPathComponent:@"Source/README.md"]];
 else [self send:j];
}
-(BOOL)applicationShouldTerminateAfterLastWindowClosed:(NSApplication*)s{return YES;}
-(void)applicationWillTerminate:(NSNotification*)n{if(self.engine.running)[self.engine terminate];if(self.hardwareTask.running)[self.hardwareTask terminate];}
@end
int main(int argc,const char **argv){@autoreleasepool{NSApplication *a=NSApplication.sharedApplication;WaveApp *d=[WaveApp new];a.delegate=d;[a run];}return 0;}
